/* 02 셀 실행 흉내 (192~193쪽) */
(function(){
  const B=$('cellSim');
  const CELLS=[
    {t:'라이브러리 불러오기',c:`import numpy as np
import pandas as pd
import matplotlib.pyplot as plt`},
    {t:'데이터 불러오기',c:`df = pd.read_csv('Life Expectancy Data.csv')`},
    {t:'② 데이터셋 정보 확인하기',c:`df.info()    <span class="c"># 속성명, 속성별 데이터 개수, 자료형 확인</span>`},
    {t:'앞의 5개 행 보기',c:`df.head()   <span class="c"># 앞의 5개 데이터 출력</span>`},
    {t:'❶ 데이터의 개수와 속성 개수',c:`df.shape`},
    {t:'❶ 속성별 결측치 개수',c:`df.isna().sum()`},
    {t:'❷ 결측치 제거하기',c:`df = df.dropna()   <span class="c"># 결측치 데이터 삭제</span>`},
    {t:'❸ Status를 0과 1로',c:`df['Status'] = df['Status'].astype(object)
df = df.replace({'Developing': 0, 'Developed': 1})
df['Status'].value_counts()`},
    {t:'더 알아보기 · 속성명의 빈칸',c:`df['BMI'].mean()`},
  ];
  let st;
  const OK='<span class="ok">✓ 실행 완료</span> <span class="muted">(출력 없음)</span>';
  const ERR=(e,why)=>`<div class="le-err">${e}</div><div class="le-why">${why}</div>`;
  const OUT=s=>`<pre class="le-out">${s}</pre>`;
  const NODF=ERR(`NameError: name 'df' is not defined`,'아직 데이터를 불러오지 않았어요. 「데이터 불러오기」 셀부터 실행하세요.');
  function isnaText(){
    const names=['Country','Year','Status','Life expectancy','Adult Mortality','infant deaths','Alcohol','percentage expenditure','Hepatitis B','Measles',' BMI','under-five deaths','Polio','Total expenditure','Diphtheria','HIV/AIDS','GDP','Population','thinness  1-19 years','thinness 5-9 years','Income composition of resources','Schooling'];
    const cnt=n=>{const k=LE_NAC.indexOf(n.trim()); return st.drop||k<0?0:LE_NACNT[k];};
    return names.map(n=>(n+' '.repeat(34)).slice(0,34)+String(cnt(n)).padStart(4)).join('\n')+'\ndtype: int64';
  }
  function run(i){
    const o=st.out;
    if(i===0){ st.imp=true; o[0]=OK; }
    else if(i===1){ if(!st.imp) o[1]=ERR(`NameError: name 'pd' is not defined`,'판다스(pd)를 아직 불러오지 않았어요. 맨 위 「라이브러리 불러오기」 셀을 먼저 실행하세요.'); else { st.df=true; st.drop=false; st.rep=false; o[1]=OK+' <span class="muted">→ df에 데이터프레임으로 저장</span>'; } }
    else if(!st.df) o[i]=NODF;
    else if(i===2) o[2]=OUT(`&lt;class 'pandas.core.frame.DataFrame'&gt;
${st.drop?'Index: 1649 entries, 0 to 2937':'RangeIndex: 2938 entries, 0 to 2937'}
Data columns (total 22 columns):
 #   Column                           Non-Null Count  Dtype
---  ------                           --------------  -----
 0   Country                          ${st.drop?1649:2938} non-null   object
 1   Year                             ${st.drop?1649:2938} non-null   int64
 2   Status                           ${st.drop?1649:2938} non-null   ${st.rep?'int64 ':'object'}
 3   Life expectancy                  ${st.drop?1649:2928} non-null   float64
 4   Adult Mortality                  ${st.drop?1649:2928} non-null   float64
 ..  ...                              ...             ...
 20  Income composition of resources  ${st.drop?1649:2771} non-null   float64
 21  Schooling                        ${st.drop?1649:2775} non-null   float64
dtypes: float64(16), int64(${st.rep?5:4}), object(${st.rep?1:2})`)+'<div class="le-why">Non-Null Count가 행 수보다 작으면 그 속성에 결측치가 있다는 뜻이에요. (가운데 속성은 줄였어요)</div>';
    else if(i===3) o[3]=OUT(`       Country  Year      Status  Life expectancy  Adult Mortality  …  Schooling
0  Afghanistan  2015  ${st.rep?'         0':'Developing'}             65.0            263.0  …       10.1
1  Afghanistan  2014  ${st.rep?'         0':'Developing'}             59.9            271.0  …       10.0
2  Afghanistan  2013  ${st.rep?'         0':'Developing'}             59.9            268.0  …        9.9
3  Afghanistan  2012  ${st.rep?'         0':'Developing'}             59.5            272.0  …        9.8
4  Afghanistan  2011  ${st.rep?'         0':'Developing'}             59.2            275.0  …        9.5

[5 rows x 22 columns]`);
    else if(i===4) o[4]=OUT(st.drop?'(1649, 22)':'(2938, 22)')+(st.drop?'<div class="le-why">결측치를 지운 뒤에는 <b>1,649행</b>이 남았어요. 2,938행 중 1,289행이 지워졌어요.</div>':'<div class="le-why">행(데이터) 2,938개, 속성 22개예요.</div>');
    else if(i===5) o[5]=OUT(isnaText())+(st.drop?'<div class="le-why">모든 속성의 결측치가 0이 되었어요.</div>':'');
    else if(i===6){ st.drop=true; o[6]=OK+' <span class="muted">→ 위의 shape·isna 셀을 다시 실행해 결과를 비교해 보세요.</span>'; }
    else if(i===7){ st.rep=true; o[7]=OUT(`Status\n0    ${st.drop?1407:2426}\n1     ${st.drop?242:512}\nName: count, dtype: int64`)+'<div class="le-why">개발도상국(Developing)은 0, 선진국(Developed)은 1이 되었어요.</div>'; }
    else if(i===8) o[8]=ERR(`KeyError: 'BMI'`,`이 데이터의 속성명은 <span class="mono">' BMI'</span>처럼 <b>앞에 빈칸</b>이 있어요. <span class="mono">df[' BMI'].mean()</span>으로 써야 평균(${st.drop?'약 38.1':'약 38.3'})이 나와요.`);
    draw();
  }
  function reset(){ st={imp:false,df:false,drop:false,rep:false,out:CELLS.map(()=>'')}; draw(); }
  function draw(){
    B.innerHTML=CELLS.map((c,i)=>`<div class="le-cell"><div class="le-ct">${c.t}</div><div class="le-cin"><button class="le-run" data-i="${i}" aria-label="${c.t} 실행">▶</button><pre class="le-code">${c.c}</pre></div>${st.out[i]?`<div class="le-cout">${st.out[i]}</div>`:''}</div>`).join('')
      +`<div class="row" style="margin-top:6px"><button class="btn sm ghost" id="csReset">처음부터</button>${st.drop&&st.rep?'<span class="ok">전처리까지 끝났어요. 03 화면에서 결과를 살펴봐요.</span>':''}</div>`;
    B.querySelectorAll('.le-run').forEach(b=>b.onclick=()=>run(+b.dataset.i));
    $('csReset').onclick=reset;
  }
  reset();
})();

/* 02 속성 안내 표 */
(function(){
  const order=['Country','Year','Status','Life expectancy','Adult Mortality','infant deaths','Alcohol','percentage expenditure','Hepatitis B','Measles','BMI','under-five deaths','Polio','Total expenditure','Diphtheria','HIV/AIDS','GDP','Population','thinness  1-19 years','thinness 5-9 years','Income composition of resources','Schooling'];
  const INT=['Year','infant deaths','Measles','under-five deaths'], OBJ=['Country','Status'];
  $('attrTbl').innerHTML='<tr><th>#</th><th class="l">속성(Column)</th><th class="l">뜻</th><th>Non-Null Count</th><th>Dtype</th></tr>'+order.map((c,i)=>{
    const k=LE_NAC.indexOf(c), nn=2938-(k<0?0:LE_NACNT[k]);
    const nm=c==='BMI'?'<span class="le-sp">␣</span>BMI':c.replace('  ',' <span class="le-sp">␣</span>');
    return `<tr${c==='Life expectancy'?' class="y"':''}><td>${i}</td><td class="l mono2">${nm}</td><td class="l">${LE_KO[c]}</td><td class="${nn<2938?'na':''}">${fmt(nn)}</td><td>${INT.includes(c)?'int64':OBJ.includes(c)?'object':'float64'}</td></tr>`;}).join('');
})();

/* 03 결측치 처리 실험실 */
(function(){
  const B=$('naLab'), N=2938;
  const M=new Int32Array(N); let p=0; for(let i=0;i<LE_MRL.length;i+=2){ M.fill(LE_MRL[i],p,p+LE_MRL[i+1]); p+=LE_MRL[i+1]; }
  const START=[]; let s=0; LE_CRUN.forEach(n=>{START.push(s); s+=n;});
  const Y=LE_NAC.indexOf('Life expectancy');
  let drop=0;
  function calc(){
    const keep=~drop; let rows=0; const cOK=new Uint8Array(LE_CRUN.length);
    LE_CRUN.forEach((n,c)=>{ for(let r=START[c];r<START[c]+n;r++) if((M[r]&keep)===0){ rows++; cOK[c]=1; } });
    let nc=0, dev=0; cOK.forEach((v,c)=>{ if(v){nc++; if(LE_CDEV[c]) dev++;} });
    return {rows,nc,dev,kor:cOK[LE_KOR]===1,cols:22-LE_NAC.filter((_,j)=>drop>>j&1).length};
  }
  const mx=Math.max(...LE_NACNT);
  function draw(){
    const r=calc(), dropped=LE_NAC.filter((_,j)=>drop>>j&1);
    const code=dropped.length?`df = df.drop(columns = [${dropped.map(c=>`'${c==='BMI'?' BMI':c==='thinness  1-19 years'?'thinness  1-19 years':c}'`).join(', ')}])\ndf = df.dropna()`:'df = df.dropna()';
    B.innerHTML=`<div class="le-na">
      <div class="le-nabars">${LE_NAC.map((c,j)=>{const on=drop>>j&1, y=j===Y;
        return `<button class="le-nab${on?' on':''}" data-j="${j}" ${y?'disabled':''} aria-pressed="${on?'true':'false'}" aria-label="${c} 결측치 ${LE_NACNT[j]}개${y?' (종속 변수라 지울 수 없음)':on?' 먼저 지우기 선택됨':''}"><span class="nm">${sname(c)}</span><span class="br"><i style="width:${LE_NACNT[j]/mx*100}%"></i></span><span class="v">${LE_NACNT[j]}</span><span class="tg">${y?'종속 변수':on?'🗑 지움':''}</span></button>`;}).join('')}</div>
      <div class="le-nares">
        <pre class="le-code sm">${code}</pre>
        <div class="le-meter"><small>남는 행</small><b>${fmt(r.rows)}</b><span>/ 2,938</span><div class="bar"><i style="width:${r.rows/N*100}%"></i></div></div>
        <div class="le-meter"><small>남는 나라</small><b>${r.nc}</b><span>/ 193</span><div class="bar"><i style="width:${r.nc/193*100}%"></i></div></div>
        <div class="le-kv"><span>속성 수 <b>${r.cols}</b></span><span>선진국 <b>${r.dev}</b> / 32개 나라</span></div>
        <div class="le-kor ${r.kor?'in':'out'}">🇰🇷 대한민국 데이터: <b>${r.kor?'남아 있어요':'모두 사라져요'}</b></div>
        <div class="row" style="margin-top:8px"><button class="btn sm ghost" id="naReset">처음처럼(그대로 dropna)</button></div>
      </div></div>
      <p class="le-msg">${dropped.length?`속성 ${dropped.length}개를 먼저 지우니 <b>${fmt(r.rows-1649)}행</b>, 나라 <b>${r.nc-133}개</b>가 더 남았어요. 대신 그 속성은 모델 학습에 쓸 수 없어요.${r.kor?'':' 대한민국은 GDP, Population, Income composition, Schooling 네 속성이 모두 비어 있어요.'}`:'그대로 <span class="mono">dropna()</span>를 하면 결측치가 하나라도 있는 행이 지워져 <b>1,649행, 133개 나라</b>만 남아요. 대한민국·일본·덴마크 등 <b>60개 나라</b>가 통째로 사라져요.'}</p>`;
    B.querySelectorAll('.le-nab').forEach(b=>b.onclick=()=>{ drop^=1<<+b.dataset.j; draw(); const nb=B.querySelector(`.le-nab[data-j="${b.dataset.j}"]`); if(nb) nb.focus(); });
    $('naReset').onclick=()=>{drop=0; draw();};
  }
  draw();
})();

/* 04 먼저 예상하기 */
const GUESS=[['국가 교육 기간','Schooling'],['소득(자원 소득에 대한 국가 개발 정도)','Income composition of resources'],['성인 사망률','Adult Mortality'],['HIV/AIDS 사망 수','HIV/AIDS'],['평균 체질량 지수','BMI'],['1인당 GDP','GDP'],['국가 총 인구수','Population'],['정부 보건 관련 지출','Total expenditure'],['소아마비 예방 접종률','Polio'],['알코올 소비량','Alcohol'],['홍역 환자 수','Measles'],['개발 상태(Status)','Status']];
chips('guessPick','guessPick',GUESS.map(g=>g[0]),true);

/* 04 상관관계 탐색기 */
(function(){
  const B=$('corrLab'), Yi=LE_COLS.indexOf('Life expectancy');
  const items=LE_COLS.map((c,i)=>({c,i,r:LE_R[i]})).filter(o=>o.i!==Yi).sort((a,b)=>b.r-a.r);
  let sel=LE_COLS.indexOf('Schooling'), showY=false;
  const ST=[{n:'개발도상국(0)',k:'#2f6fd0',cnt:1407,mean:67.69,min:44.0},{n:'선진국(1)',k:'#e0702b',cnt:242,mean:78.69,min:69.9}];
  const Si=LE_COLS.indexOf('Status');
  const guessed=()=>{const g=(MEMO.guessPick||'').split(' · '); return GUESS.filter(x=>g.includes(x[0])).map(x=>x[1]);};
  const word=r=>{const a=Math.abs(r); return a<0.2?'관계가 거의 없어요':(r>0?'양의 상관관계':'음의 상관관계')+(a>=0.5?'가 커요':'가 조금 있어요');};
  const nice=v=>Math.abs(v)>=1e6?(v/1e6).toFixed(v>=1e8?0:1)+'M':Math.abs(v)>=1e4?Math.round(v/1e3)+'k':Math.abs(v)>=100?Math.round(v):(Math.round(v*100)/100);
  function scatter(i){
    const o={W:460,H:290,L:44,R:12,T:12,B:40}, h=LE_H[LE_COLS[i]], x0=h[1][0], x1=h[1][10], y0=40, y1=90;
    const sx=v=>o.L+(v-x0)/((x1-x0)||1)*(o.W-o.L-o.R), sy=v=>o.H-o.B-(v-y0)/(y1-y0)*(o.H-o.T-o.B);
    let g=`<svg viewBox="0 0 ${o.W} ${o.H}" role="img" aria-label="${LE_COLS[i]}와 기대 수명의 산점도">`;
    for(let v=40;v<=90;v+=10) g+=`<line class="gl" x1="${o.L}" x2="${o.W-o.R}" y1="${sy(v)}" y2="${sy(v)}"/><text class="tk" x="${o.L-6}" y="${sy(v)+3}" text-anchor="end">${v}</text>`;
    if(i===Si){
      [0,1].forEach(s=>{ const cx=o.L+(s?0.72:0.28)*(o.W-o.L-o.R);
        LE_D.forEach((d,k)=>{ if(d[Si]!==s) return; const jx=((k*37)%41-20)*2.2; g+=`<circle cx="${cx+jx}" cy="${sy(d[Yi])}" r="2.6" fill="${ST[s].k}" opacity=".55"/>`; });
        g+=`<line x1="${cx-60}" x2="${cx+60}" y1="${sy(ST[s].mean)}" y2="${sy(ST[s].mean)}" stroke="#16202c" stroke-width="2.5"/><text class="axl" x="${cx}" y="${sy(ST[s].mean)-6}" text-anchor="middle" fill="#16202c">평균 ${ST[s].mean}</text>`;
        g+=`<line x1="${cx-60}" x2="${cx+60}" y1="${sy(ST[s].min)}" y2="${sy(ST[s].min)}" stroke="#d64535" stroke-width="1.5" stroke-dasharray="4 3"/><text class="tk" x="${cx}" y="${sy(ST[s].min)+16}" text-anchor="middle" fill="#d64535">최솟값 ${ST[s].min}</text>`;
        g+=`<text class="axl" x="${cx}" y="${o.H-14}" text-anchor="middle">${ST[s].n}</text>`; });
      if(sy(65)>0) g+=`<line x1="${o.L}" x2="${o.W-o.R}" y1="${sy(65)}" y2="${sy(65)}" stroke="#c98a00" stroke-dasharray="2 4"/><text class="tk" x="${o.W-o.R}" y="${sy(65)-3}" text-anchor="end" fill="#c98a00">65세</text>`;
    } else {
      for(let t=0;t<=10;t+=2.5){ const v=x0+(x1-x0)*t/10; g+=`<text class="tk" x="${sx(v)}" y="${o.H-o.B+14}" text-anchor="middle">${nice(v)}</text>`; }
      LE_D.forEach(d=>{ g+=`<circle cx="${sx(d[i])}" cy="${sy(d[Yi])}" r="2.6" fill="${ST[d[Si]].k}" opacity=".5"/>`; });
      g+=`<text class="axl" x="${(o.L+o.W-o.R)/2}" y="${o.H-6}" text-anchor="middle">${sname(LE_COLS[i])} (${LE_AXK[LE_COLS[i]]||LE_KO[LE_COLS[i]]})</text>`;
    }
    g+=`<text class="axl" x="12" y="${(o.T+o.H-o.B)/2}" transform="rotate(-90 12 ${(o.T+o.H-o.B)/2})" text-anchor="middle">기대 수명(세)</text></svg>`;
    return g;
  }
  function hist(c){
    const h=LE_H[c], mx=Math.max(...h[0]), o={W:460,H:170,L:44,R:12,T:10,B:34}, bw=(o.W-o.L-o.R)/10;
    let g=`<svg viewBox="0 0 ${o.W} ${o.H}" role="img" aria-label="${c} 히스토그램">`;
    h[0].forEach((n,k)=>{ const hh=n/mx*(o.H-o.T-o.B); g+=`<rect x="${o.L+k*bw+1}" y="${o.H-o.B-hh}" width="${bw-2}" height="${hh}" fill="#9b4fc4" opacity=".75"><title>${nice(h[1][k])}~${nice(h[1][k+1])}: ${n}행</title></rect><text class="tk" x="${o.L+k*bw+bw/2}" y="${o.H-o.B-hh-3}" text-anchor="middle">${n}</text>`; });
    for(let k=0;k<=10;k+=2) g+=`<text class="tk" x="${o.L+k*bw}" y="${o.H-o.B+13}" text-anchor="middle">${nice(h[1][k])}</text>`;
    g+=`<text class="axl" x="${(o.L+o.W-o.R)/2}" y="${o.H-4}" text-anchor="middle">${c}${c==='Life expectancy'?' (기대 수명)':''} · 막대 = 행 수</text></svg>`;
    return g;
  }
  function draw(){
    const gs=guessed(), c=LE_COLS[sel], r=LE_R[sel];
    const bars=items.map(o=>`<button class="le-cb${o.i===sel&&!showY?' on':''}" data-i="${o.i}" aria-pressed="${o.i===sel&&!showY?'true':'false'}" aria-label="${o.c} 상관계수 ${o.r}"><span class="nm">${gs.includes(o.c)?'★ ':''}${sname(o.c)}</span><span class="br"><i class="${o.r<0?'neg':'pos'}" style="${o.r<0?'right:50%':'left:50%'};width:${Math.abs(o.r)*50}%"></i></span><span class="v">${o.r.toFixed(2)}</span></button>`).join('');
    const info=showY?`<b>기대 수명(Life expectancy)</b>의 분포예요. 최빈 구간은 <b>71.0~75.5세</b>(526행)이고, 약 70~75세까지 급격히 증가하다가 75세 이후 급격히 줄어요.`
      :sel===Si?`<b>Status</b>: 상관계수 <b>${r.toFixed(2)}</b>. 선진국(242행)의 평균 기대 수명은 <b>78.7세</b>, 개발도상국(1,407행)은 <b>67.7세</b>예요. 선진국의 최솟값은 69.9세라 <b>65세 미만인 선진국은 없어요</b>. (바이올린 그래프 해석과 같아요)`
      :`<b>${c}</b>(${LE_KO[c]}): 상관계수 <b>${r.toFixed(2)}</b> → ${word(r)}.${c==='Polio'?' 히스토그램을 보면 예방 접종률이 90% 이상인 경우가 가장 많아요.':''}${c==='Population'?' 인구수는 기대 수명과 관계가 거의 없어요(교과서 해석과 같아요).':''}${c==='GDP'?' GDP가 낮은 쪽에 점이 몰려 있고, 선진국(주황)은 GDP와 기대 수명이 함께 높은 쪽에 많아요.':''}`;
    B.innerHTML=`<div class="le-cl"><div class="le-plot" id="clPlot"><div class="row" style="margin-bottom:6px"><button class="btn sm ghost${showY?' on':''}" id="clY" aria-pressed="${showY?'true':'false'}">① 기대 수명 히스토그램</button><span class="le-leg"><i style="background:#2f6fd0"></i>개발도상국 <i style="background:#e0702b"></i>선진국</span></div>
      ${showY?hist('Life expectancy'):scatter(sel)+(sel===Si?'':hist(c))}
      <p class="le-msg">${info}</p></div>
      <div class="le-bars" role="group" aria-label="기대 수명과의 상관계수">${'<div class="le-axis"><span></span><span class="sc"><i>−1</i><i>0</i><i>+1</i></span><span></span></div>'+bars}</div></div>
      <p class="note">점은 1,649행 중 600행만 그렸고, 상관계수와 히스토그램은 1,649행 전체로 계산했어요. 막대의 <b>길이</b>가 관계의 세기, <b>방향</b>(오른쪽 +, 왼쪽 −)이 함께 커지는지(양) 반대로 움직이는지(음)를 나타내요.</p>`;
    const bs=[...B.querySelectorAll('.le-cb')];
    bs.forEach((b,k)=>{ b.onclick=()=>{ sel=+b.dataset.i; showY=false; draw(); focusSel(); };
      b.onkeydown=e=>{ if(e.key==='ArrowDown'||e.key==='ArrowUp'){ e.preventDefault(); const n=bs[Math.max(0,Math.min(bs.length-1,k+(e.key==='ArrowDown'?1:-1)))]; sel=+n.dataset.i; showY=false; draw(); focusSel(); } }; });
    $('clY').onclick=()=>{ showY=!showY; draw(); };
  }
  function focusSel(){ const b=B.querySelector('.le-cb.on'); if(b) b.focus({preventScroll:true}); const p=$('clPlot'); if(p&&window.innerWidth<760){ const r=p.getBoundingClientRect(); if(r.bottom<60||r.top>window.innerHeight-80) p.scrollIntoView({behavior:'smooth',block:'start'}); } }
  $('guessPick').addEventListener('memo',draw);
  draw();
})();

/* 05 빈칸 확인 · 스스로 점검 */
document.querySelectorAll('.blank').forEach(b=>{ b.setAttribute('aria-label','빈칸, 눌러서 답 보기'); b.onclick=()=>{ b.textContent=b.dataset.a; b.classList.add('on'); b.setAttribute('aria-label','답: '+b.dataset.a); }; });
chips('selfCheck','selfCheckPick',['SDGs 목표에서 주제를 골라 문제를 정의할 수 있다','info( )와 head( )로 데이터셋 정보를 확인할 수 있다','결측치를 확인하고 제거할 수 있다','범주형 데이터를 숫자로 바꿀 수 있다','그래프로 기대 수명에 영향을 미치는 속성을 찾을 수 있다'],true);

const MEMOLIST=[['planMemo','학습 계획 1 · 기대 수명과 SDGs의 관계'],['wantMemo','학습 계획 2 · 배우고 싶은 것'],['roleMemo','문제 정의와 모둠원 역할'],['naMemo','dropna로 사라지는 데이터와 내 선택'],['guessPick','먼저 예상한 속성'],['vizMemo','해 보기 · 시각화 방법과 기대 수명에 영향을 미치는 속성'],['causeMemo','교육 기간을 늘리면 기대 수명이 늘까?'],['selfCheckPick','스스로 점검: 할 수 있게 된 것']];
onShow[6]=()=>memoSummary('msum',MEMOLIST);
